//! The chain methods against reference data of MultiOptPy's `nebmain` on a Lennard-Jones
//! path (`tests/golden/neb_*.json`, generated by `tools/golden/run_neb_reference.py`): every
//! iteration starts from the chain MultiOptPy evaluated and must end at the chain it
//! evaluated next.
//!
//! This file is part of mopt-rs.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod mop_units;

use std::path::PathBuf;

use faer::{Col, Mat};
use mopt_rs::core_infra::json::JsonValue;
use mopt_rs::domain::{positions, Bohr, Element, EvalRequest, MolecularSystem, SpinCharge};
use mopt_rs::path::band::align::align_chain_in_sequence;
use mopt_rs::path::band::fire::{ChainFire, ChainFireSettings};
use mopt_rs::path::band::force::UpwindProjection;
use mopt_rs::path::band::redistribute::{equal_spacing, towards_predicted_maxima, Curve};
use mopt_rs::path::band::rfo::{AlongChain, ChainRfo, ChainRfoSettings};
use mopt_rs::path::band::trust::{limit_steps, steepest_steps, FixedEnds};
use mopt_rs::path::band::{path_lengths, ChainKind, Compatibility, BLOCK_ATOM};

fn golden(name: &str) -> JsonValue {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    JsonValue::parse(&text).unwrap()
}

/// All numbers below `v`, in order.
fn floats(v: &JsonValue) -> Vec<f64> {
    match v.as_array() {
        Some(items) => items.iter().flat_map(floats).collect(),
        None => vec![v.as_f64().unwrap()],
    }
}

/// The chains of a case in Bohr: iteration, image, coordinates.
fn chains(case: &JsonValue) -> Vec<Vec<Col<f64>>> {
    case.get("chains_angstrom")
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .map(|chain| {
            chain
                .as_array()
                .unwrap()
                .iter()
                .map(|image| {
                    let x = floats(image);
                    Col::from_fn(x.len(), |k| mop_units::mop_bohr(x[k]))
                })
                .collect()
        })
        .collect()
}

fn rows(case: &JsonValue, key: &str) -> Vec<Vec<f64>> {
    case.get(key)
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect()
}

fn argon(point: &Col<f64>) -> MolecularSystem {
    let atoms = point.nrows() / 3;
    let element = Element::parse_token("Ar").unwrap();
    let pos: Vec<[f64; 3]> = (0..atoms)
        .map(|a| [point[3 * a], point[3 * a + 1], point[3 * a + 2]])
        .collect();
    MolecularSystem::new(
        vec![element; atoms],
        &positions::<Bohr>(&pos),
        SpinCharge::default(),
        None,
    )
    .unwrap()
}

struct Case {
    file: &'static str,
    ends: FixedEnds,
    climb_after: Option<usize>,
    steepest_from: Option<usize>,
    /// Equal spacing every this many iterations (`-ad`).
    equal_spacing_every: Option<usize>,
}

/// One case: every iteration of MultiOptPy is repeated from its chain.
fn follows_multioptpy(case: &Case) {
    let data = golden(case.file);
    let chains = chains(&data);
    let energies = rows(&data, "energies_hartree");
    let lengths = rows(&data, "path_length");
    let perp_rms = rows(&data, "perp_rms_gradient");
    let orthogonality = rows(&data, "orthogonality");
    let rule = UpwindProjection {
        block: BLOCK_ATOM,
        climb_after: case.climb_after,
        compatibility: Compatibility::MultiOptPy,
    };
    let mut fire = ChainFire::new(ChainFireSettings::default());
    let mut previous: Option<Vec<Col<f64>>> = None;
    let first = chains[0].clone();
    for (iteration, chain) in chains.iter().enumerate().take(energies.len()) {
        let mut found_energies = Vec::new();
        let mut gradients = Vec::new();
        for image in chain {
            let out = mop_units::lennard_jones(&argon(image), &EvalRequest::ENERGY_GRAD).unwrap();
            found_energies.push(out.energy.value());
            gradients.push(out.gradient_bohr);
        }
        for (a, b) in found_energies.iter().zip(&energies[iteration]) {
            assert!(
                (a - b).abs() < 1e-11,
                "{}: energy {a} against {b}",
                case.file
            );
        }
        for (a, b) in path_lengths(chain, ChainKind::Atoms)
            .iter()
            .zip(&lengths[iteration])
        {
            assert!(
                (a - b).abs() < 1e-9,
                "{}: length {a} against {b}",
                case.file
            );
        }
        let forces = rule
            .forces(chain, &found_energies, &gradients, iteration)
            .unwrap();
        // What MultiOptPy logs of its forces: their root mean square, and their cosine
        // with the gradient.
        for (i, force) in forces.forces.iter().enumerate() {
            let n = force.nrows() as f64;
            let rms = (force.iter().map(|x| x * x).sum::<f64>() / n).sqrt();
            assert!(
                (rms - perp_rms[iteration][i]).abs() < 1e-11,
                "{} iteration {iteration} image {i}: rms {rms} against {}",
                case.file,
                perp_rms[iteration][i]
            );
            let dot: f64 = force
                .iter()
                .zip(gradients[i].iter())
                .map(|(a, b)| a * b)
                .sum();
            let norms = (n.sqrt() * rms) * gradients[i].iter().map(|x| x * x).sum::<f64>().sqrt();
            if norms > 1e-20 {
                assert!((dot / norms - orthogonality[iteration][i]).abs() < 1e-8);
            }
        }
        let steps = match case.steepest_from {
            Some(from) if iteration >= from => steepest_steps(chain, &forces.forces, case.ends),
            _ => {
                let proposed = fire.displacements(&forces.forces, previous.as_deref());
                let legacy = Compatibility::MultiOptPy;
                limit_steps(chain, &forces.forces, &proposed, case.ends, legacy).steps
            }
        };
        let mut next: Vec<Col<f64>> = chain.iter().zip(&steps).map(|(x, d)| x + d).collect();
        let last = next.len() - 1;
        if case.ends.first {
            next[0] = first[0].clone();
        }
        if case.ends.last {
            next[last] = first[last].clone();
        }
        align_chain_in_sequence(&mut next);
        if case
            .equal_spacing_every
            .is_some_and(|every| iteration > 0 && iteration % every == 0)
        {
            next = equal_spacing(&next, ChainKind::Atoms, Curve::Polyline);
        }
        let expected = &chains[iteration + 1];
        for (i, (a, b)) in next.iter().zip(expected).enumerate() {
            let worst = (a - b).iter().fold(0.0_f64, |m, d| m.max(d.abs()));
            assert!(
                worst < 5e-11,
                "{} iteration {iteration} image {i}: off by {worst} Bohr",
                case.file
            );
        }
        previous = Some(forces.forces);
    }
}

#[test]
fn the_default_of_multioptpy_is_followed_step_by_step() {
    follows_multioptpy(&Case {
        file: "neb_lj_ar7_default.json",
        ends: FixedEnds::default(),
        climb_after: None,
        steepest_from: None,
        equal_spacing_every: None,
    });
}

#[test]
fn fixed_ends_climbing_and_steepest_descent_of_multioptpy_are_followed() {
    follows_multioptpy(&Case {
        file: "neb_lj_ar7_fixed_ends.json",
        ends: FixedEnds::from_code(3),
        climb_after: None,
        steepest_from: None,
        equal_spacing_every: None,
    });
    follows_multioptpy(&Case {
        file: "neb_lj_ar7_climbing.json",
        ends: FixedEnds::default(),
        climb_after: Some(3),
        steepest_from: None,
        equal_spacing_every: None,
    });
    follows_multioptpy(&Case {
        file: "neb_lj_ar7_steepest.json",
        ends: FixedEnds::default(),
        climb_after: None,
        steepest_from: Some(3),
        equal_spacing_every: None,
    });
}

#[test]
fn equal_spacing_of_multioptpy_is_followed() {
    follows_multioptpy(&Case {
        file: "neb_lj_ar7_equal_spacing.json",
        ends: FixedEnds::default(),
        climb_after: None,
        steepest_from: None,
        equal_spacing_every: Some(2),
    });
}

/// The Hessians of the images in iteration `k` of a case, as MultiOptPy loaded them.
fn hessians(case: &JsonValue, k: usize) -> Vec<Mat<f64>> {
    case.get("hessians").unwrap().as_array().unwrap()[k]
        .as_array()
        .unwrap()
        .iter()
        .map(|h| {
            let values = floats(h);
            let n = (values.len() as f64).sqrt().round() as usize;
            Mat::from_fn(n, n, |i, j| values[i * n + j])
        })
        .collect()
}

fn worst(a: &Mat<f64>, b: &Mat<f64>) -> f64 {
    let mut out = 0.0_f64;
    for i in 0..a.nrows() {
        for j in 0..a.ncols() {
            out = out.max((a[(i, j)] - b[(i, j)]).abs());
        }
    }
    out
}

/// The way nebmain is used in the articles of the author, without the redistribution:
/// model Hessians of the images at the start, then half a step along the forces and half
/// a quasi-Newton step of every image.
#[test]
fn the_mixed_steps_of_multioptpy_are_followed() {
    mixed_steps_follow_multioptpy("neb_lj_ar7_article_no_redistribution.json", None);
}

/// The same with the images put towards the predicted maxima of the energy profile every
/// second iteration: nebmain as the articles of the author run it.
#[test]
fn the_way_of_the_articles_is_followed() {
    mixed_steps_follow_multioptpy("neb_lj_ar7_article.json", Some(2));
}

fn mixed_steps_follow_multioptpy(file: &str, predicted_every: Option<usize>) {
    let data = golden(file);
    let chains = chains(&data);
    let energies = rows(&data, "energies_hartree");
    let rule = UpwindProjection {
        block: BLOCK_ATOM,
        climb_after: None,
        compatibility: Compatibility::MultiOptPy,
    };
    let legacy = Compatibility::MultiOptPy;
    let ends = FixedEnds::default();
    let images = chains[0].len();
    let n = chains[0][0].nrows();
    let template = argon(&chains[0][0]);
    // One pair per Hessian update, as MultiOptPy's block updates in effect use.
    let settings = ChainRfoSettings {
        pairs: Some(1),
        ..ChainRfoSettings::default()
    };
    let mut rfo = ChainRfo::new(settings, images, n, Some(template), rule).unwrap();
    for (i, hessian) in hessians(&data, 0).into_iter().enumerate() {
        rfo.set_hessian(i, hessian).unwrap();
    }
    let mut previous: Option<Vec<Col<f64>>> = None;
    for (iteration, chain) in chains.iter().enumerate().take(energies.len()) {
        let mut found_energies = Vec::new();
        let mut gradients = Vec::new();
        for image in chain {
            let out = mop_units::lennard_jones(&argon(image), &EvalRequest::ENERGY_GRAD).unwrap();
            found_energies.push(out.energy.value());
            gradients.push(out.gradient_bohr);
        }
        for (a, b) in found_energies.iter().zip(&energies[iteration]) {
            assert!(
                (a - b).abs() < 1e-10,
                "iteration {iteration}: energy {a} against {b}"
            );
        }
        let forces = rule
            .forces(chain, &found_energies, &gradients, iteration)
            .unwrap();
        let along = AlongChain {
            removed: &forces.removed,
            directions: &forces.directions,
            climbing: &forces.climbing,
        };
        let newton = rfo
            .steps(chain, &found_energies, &gradients, along)
            .unwrap();
        if iteration == 0 {
            // What MultiOptPy saved after its first iteration: the model Hessian with
            // the curvature along the chain added.
            for (i, expected) in hessians(&data, 1).iter().enumerate() {
                let off = worst(&rfo.hessian(i).unwrap(), expected);
                assert!(
                    off < 1e-9,
                    "Hessian of image {i} after iteration 0: off by {off}"
                );
            }
        }
        // The steps of the minimizers themselves (MultiOptPy's sign: subtracted), limited
        // in length as MultiOptPy does it after recording them.
        let recorded = data.get("newton_steps").unwrap().as_array().unwrap()[iteration]
            .as_array()
            .unwrap();
        for (i, step) in newton.iter().enumerate() {
            let raw = floats(&recorded[i]);
            let length = raw.iter().map(|v| v * v).sum::<f64>().sqrt();
            let limit: f64 = if i == 0 || i == images - 1 { 0.2 } else { 0.1 };
            let scale = if length > 1e-8 {
                limit.min(length) / length
            } else {
                1.0
            };
            let off = (0..n).fold(0.0_f64, |m, k| m.max((step[k] + scale * raw[k]).abs()));
            assert!(
                off < 1e-8,
                "iteration {iteration} image {i}: quasi-Newton step off by {off} (length {length})"
            );
        }
        // MultiOptPy's quasi-Newton vectors are subtracted, and they pass the limits of
        // the chain with the gradients in the place of the forces.
        let subtracted: Vec<Col<f64>> = newton.iter().map(|d| -d).collect();
        let newton = limit_steps(chain, &gradients, &subtracted, ends, legacy).steps;
        // A new step rule in every iteration, as MultiOptPy creates it.
        let mut fire = ChainFire::new(ChainFireSettings::default());
        let proposed = fire.displacements(&forces.forces, previous.as_deref());
        let along = limit_steps(chain, &forces.forces, &proposed, ends, legacy).steps;
        let mut next: Vec<Col<f64>> = (0..images)
            .map(|i| {
                if i == 0 || i == images - 1 {
                    &chain[i] - &newton[i]
                } else {
                    &chain[i] + 0.5 * &along[i] - 0.5 * &newton[i]
                }
            })
            .collect();
        align_chain_in_sequence(&mut next);
        if predicted_every.is_some_and(|every| iteration > 0 && iteration % every == 0) {
            next = towards_predicted_maxima(&next, &found_energies, &gradients, legacy);
        }
        for (i, (a, b)) in next.iter().zip(&chains[iteration + 1]).enumerate() {
            let off = (a - b).iter().fold(0.0_f64, |m, d| m.max(d.abs()));
            assert!(
                off < 1e-7,
                "{file} iteration {iteration} image {i}: off by {off} Bohr"
            );
        }
        previous = Some(forces.forces);
    }
}
